namespace ZoneEngine.Core.Nascence.Quests
{
    #region Usings ...

    using System;

    using AORebirth.Core.Entities;

    using Utility;

    using ZoneEngine.Core;

    #endregion

    /// <summary>
    /// Capture-backed Rosenblatt Hiathlin QuestFullUpdate packets (20260822-070136).
    /// </summary>
    internal static class RosenblattHiathlinPacketSender
    {
        private const int CapturedCharacterInstance = unchecked((int)0x78D84040);
        private const int CapturedDeleteMissionInstance = unchecked((int)0x55AA388F);

        /// <summary>Capture accept/kill-stage QFU duration (0x2760 = 10080 seconds).</summary>
        private const int MissionDurationSeconds = 0x2760;

        /// <summary>Capture turn-in-stage QFU duration (0x21C = 540 seconds).</summary>
        private const int TurnInMissionDurationSeconds = 0x21C;

        /// <summary>Same GameTimeMessage epoch as MissionAcceptService / DojaChipPacketSender.</summary>
        private const long ClientClockBaseSeconds = 1_201_445_827L;

        private const string AcceptQuestFullUpdateHex =
            "";

        private const string Kill4QuestFullUpdateHex =
            "";

        private const string Kill3QuestFullUpdateHex =
            "";

        private const string Kill2QuestFullUpdateHex =
            "";

        private const string Kill1QuestFullUpdateHex =
            "";

        private const string RegularCompleteQuestFullUpdateHex =
            "";

        private const string TurnInReadyQuestFullUpdateHex =
            "";

        /// <summary>Capture IN #29401 Action59 delete for Mission:55AA388F.</summary>
        private const string CapturedAction59DeleteHex =
            "7366000A0001003700000DBD78D840405E4777700000C35078D84040000000003B000000000000DAC355AA388F0000DAC355AA388F0000";

        /// <summary>Capture IN #29402 Quest/Delete for Mission:55AA388F.</summary>
        private const string CapturedQuestDeleteHex =
            "7367000A0001003500000DBD78D84040212C487A0000C35078D840400000000001000000000000DAC355AA388F0000000000000000";

        internal static bool TrySendQuestFullUpdate(ICharacter character, string questId)
        {
            string hex = ResolveHex(questId);
            return !string.IsNullOrEmpty(hex)
                   && TrySendRaw(character, hex, ResolveMissionDurationSeconds(questId));
        }

        internal static bool TrySendQuestDelete(ICharacter character, string questId)
        {
            int instance;
            if (!TryResolveMissionInstance(questId, out instance) || !CanSend(character))
            {
                return false;
            }

            try
            {
                var client = (ZoneClient)character.Controller.Client;

                byte[] action59 = HexToBytes(CapturedAction59DeleteHex);
                ReplaceInstance(action59, CapturedCharacterInstance, character.Identity.Instance);
                ReplaceInstance(action59, CapturedDeleteMissionInstance, instance);
                byte[] questDelete = HexToBytes(CapturedQuestDeleteHex);
                ReplaceInstance(questDelete, CapturedCharacterInstance, character.Identity.Instance);
                ReplaceInstance(questDelete, CapturedDeleteMissionInstance, instance);
                client.EnqueueOutboundCompressedBuffer(action59);
                client.EnqueueOutboundCompressedBuffer(questDelete);

                LogUtil.Debug(
                    DebugInfoDetail.Error,
                    "ROSENBLATT_HIATHLIN QuestDelete quest=" + questId
                    + " char=" + character.Identity.Instance.ToString("X8"));
                return true;
            }
            catch (Exception exception)
            {
                LogUtil.Debug(DebugInfoDetail.Error, "ROSENBLATT_HIATHLIN QuestDelete failed: " + exception.Message);
                return false;
            }
        }

        private static string ResolveHex(string questId)
        {
            if (string.IsNullOrWhiteSpace(questId))
            {
                return null;
            }

            if (string.Equals(questId, RosenblattHiathlinInteractionRules.QuestAccept, StringComparison.OrdinalIgnoreCase))
            {
                return AcceptQuestFullUpdateHex;
            }

            if (string.Equals(questId, RosenblattHiathlinInteractionRules.QuestKill4Remaining, StringComparison.OrdinalIgnoreCase))
            {
                return Kill4QuestFullUpdateHex;
            }

            if (string.Equals(questId, RosenblattHiathlinInteractionRules.QuestKill3Remaining, StringComparison.OrdinalIgnoreCase))
            {
                return Kill3QuestFullUpdateHex;
            }

            if (string.Equals(questId, RosenblattHiathlinInteractionRules.QuestKill2Remaining, StringComparison.OrdinalIgnoreCase))
            {
                return Kill2QuestFullUpdateHex;
            }

            if (string.Equals(questId, RosenblattHiathlinInteractionRules.QuestKill1Remaining, StringComparison.OrdinalIgnoreCase))
            {
                return Kill1QuestFullUpdateHex;
            }

            if (string.Equals(
                    questId,
                    RosenblattHiathlinInteractionRules.QuestRegularKillsComplete,
                    StringComparison.OrdinalIgnoreCase))
            {
                return RegularCompleteQuestFullUpdateHex;
            }

            if (string.Equals(questId, RosenblattHiathlinInteractionRules.QuestTurnInReady, StringComparison.OrdinalIgnoreCase))
            {
                return TurnInReadyQuestFullUpdateHex;
            }

            return null;
        }

        private static int ResolveMissionDurationSeconds(string questId)
        {
            if (string.Equals(
                    questId,
                    RosenblattHiathlinInteractionRules.QuestRegularKillsComplete,
                    StringComparison.OrdinalIgnoreCase)
                || string.Equals(
                    questId,
                    RosenblattHiathlinInteractionRules.QuestTurnInReady,
                    StringComparison.OrdinalIgnoreCase))
            {
                return TurnInMissionDurationSeconds;
            }

            return MissionDurationSeconds;
        }

        private static bool TryResolveMissionInstance(string questId, out int instance)
        {
            instance = 0;
            if (string.IsNullOrWhiteSpace(questId))
            {
                return false;
            }

            string normalized = questId.Trim();
            int colon = normalized.LastIndexOf(':');
            string hex = colon >= 0 ? normalized.Substring(colon + 1) : normalized;
            return int.TryParse(
                hex,
                System.Globalization.NumberStyles.HexNumber,
                System.Globalization.CultureInfo.InvariantCulture,
                out instance);
        }

        private static bool TrySendRaw(ICharacter character, string hex, int durationSeconds)
        {
            if (!CanSend(character) || string.IsNullOrWhiteSpace(hex))
            {
                return false;
            }

            try
            {
                var client = character.Controller.Client as ZoneClient;
                byte[] packet = HexToBytes(hex);
                ReplaceInstance(packet, CapturedCharacterInstance, character.Identity.Instance);
                PatchMissionExpiryBand(packet, client, durationSeconds);
                client.EnqueueOutboundCompressedBuffer(packet);
                return true;
            }
            catch (Exception exception)
            {
                LogUtil.Debug(DebugInfoDetail.Error, "ROSENBLATT_HIATHLIN QuestFullUpdate failed: " + exception.Message);
                return false;
            }
        }

        /// <summary>
        /// Rewrite QuestActions[0].UnknownHash1 AbsoluteTime expiry (0x6A80xxxx..0x6A92xxxx band).
        /// </summary>
        private static void PatchMissionExpiryBand(byte[] packet, ZoneClient client, int durationSeconds)
        {
            if (packet == null || client == null || durationSeconds <= 0)
            {
                return;
            }

            double secondsSinceSync = (DateTime.UtcNow - client.LastGameTimeSyncUtc).TotalSeconds;
            if (secondsSinceSync < 0)
            {
                secondsSinceSync = 0;
            }

            if (secondsSinceSync > durationSeconds)
            {
                secondsSinceSync = 0;
                client.LastGameTimeSyncUtc = DateTime.UtcNow;
            }

            long clientClockNow = ClientClockBaseSeconds + (long)secondsSinceSync;
            long expiry = clientClockNow + durationSeconds;

            for (int i = 0; i + 4 <= packet.Length; i++)
            {
                int value = (packet[i] << 24)
                            | (packet[i + 1] << 16)
                            | (packet[i + 2] << 8)
                            | packet[i + 3];
                int band = value & unchecked((int)0xFFFF0000);
                if (band < unchecked((int)0x6A800000) || band > unchecked((int)0x6AC00000))
                {
                    continue;
                }

                WriteInt32BigEndian(packet, i, (int)expiry);
                return;
            }
        }

        private static void WriteInt32BigEndian(byte[] packet, int offset, int value)
        {
            packet[offset] = (byte)(value >> 24);
            packet[offset + 1] = (byte)(value >> 16);
            packet[offset + 2] = (byte)(value >> 8);
            packet[offset + 3] = (byte)value;
        }

        private static bool CanSend(ICharacter character)
        {
            return character != null
                   && character.Controller != null
                   && character.Controller.Client is ZoneClient;
        }

        private static void ReplaceInstance(byte[] packet, int from, int to)
        {
            byte f0 = (byte)(from >> 24);
            byte f1 = (byte)(from >> 16);
            byte f2 = (byte)(from >> 8);
            byte f3 = (byte)from;

            for (int i = 0; i + 4 <= packet.Length; i++)
            {
                if (packet[i] == f0 && packet[i + 1] == f1 && packet[i + 2] == f2 && packet[i + 3] == f3)
                {
                    packet[i] = (byte)(to >> 24);
                    packet[i + 1] = (byte)(to >> 16);
                    packet[i + 2] = (byte)(to >> 8);
                    packet[i + 3] = (byte)to;
                    i += 3;
                }
            }
        }

        private static byte[] HexToBytes(string hex)
        {
            int length = hex.Length / 2;
            byte[] bytes = new byte[length];
            for (int i = 0; i < length; i++)
            {
                bytes[i] = Convert.ToByte(hex.Substring(i * 2, 2), 16);
            }

            return bytes;
        }
    }
}
